#!/usr/bin/env bash
# Tests for prepare-release.sh. Needs no git and no network: every case builds
# small fixture files in a scratch directory and runs the script against them.
# Usage: .github/scripts/tests/prepare-release-test.sh
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
script="$here/../prepare-release.sh"
section="$here/../changelog-section.sh"

scratch="$(mktemp -d "$here/.scratch.XXXXXX")"
trap 'rm -rf "$scratch"' EXIT

pass=0
fail=0
check() { # check <name> <condition exit status>
  if [ "$2" -eq 0 ]; then
    pass=$((pass + 1))
    echo "ok   - $1"
  else
    fail=$((fail + 1))
    echo "FAIL - $1"
  fi
}

# new_fixture <dir> <current version> <unreleased body>
# Builds Cargo.toml, Cargo.lock and CHANGELOG.md shaped like the real ones,
# including a dependency whose version must never be touched.
new_fixture() {
  local dir="$1" version="$2" body="$3"
  mkdir -p "$dir"
  cat > "$dir/Cargo.toml" <<TOML
[package]
name = "lazarobox-shell"
version = "$version"
edition = "2024"

[dependencies]
serde = { version = "1.0.0" }
TOML
  cat > "$dir/Cargo.lock" <<LOCK
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "serde"
version = "$version"

[[package]]
name = "lazarobox-shell"
version = "$version"
dependencies = [
 "serde",
]

[[package]]
name = "zzz"
version = "$version"
LOCK
  {
    printf '# Changelog\n\nIntro.\n\n## [Unreleased]\n'
    printf '%s' "$body"
    cat <<'LOG'

## [1.0.0] - 2026-10-30

### Fixed

- Old fix.

[Unreleased]: https://github.com/o/r/compare/v1.0.0...HEAD
[1.0.0]: https://github.com/o/r/compare/v1.0.0-rc.1...v1.0.0
LOG
  } > "$dir/CHANGELOG.md"
}

changed_body=$'\n### Changed\n\n- A change.\n  continued here.\n'
added_body=$'\n### Added\n\n- A feature.\n\n### Fixed\n\n- A fix.\n'

cargo_version() { awk -F'"' '/^version/ {print $2; exit}' "$1/Cargo.toml"; }

# auto -> patch when Unreleased has no Added heading
d="$scratch/auto-patch"
new_fixture "$d" 1.0.0 "$changed_body"
out="$("$script" auto "$d" 2026-11-01 | tail -n 1)"
check "auto without Added prints 1.0.1" "$([ "$out" = 1.0.1 ] && echo 0 || echo 1)"
check "auto without Added bumps Cargo.toml" "$([ "$(cargo_version "$d")" = 1.0.1 ] && echo 0 || echo 1)"

# auto -> minor when Unreleased has an Added heading
d="$scratch/auto-minor"
new_fixture "$d" 1.0.0 "$added_body"
out="$("$script" auto "$d" 2026-11-01 | tail -n 1)"
check "auto with Added prints 1.1.0" "$([ "$out" = 1.1.0 ] && echo 0 || echo 1)"

# explicit major, even when only Changed is present
d="$scratch/major"
new_fixture "$d" 1.4.7 "$changed_body"
out="$("$script" major "$d" 2026-11-01 | tail -n 1)"
check "explicit major prints 2.0.0" "$([ "$out" = 2.0.0 ] && echo 0 || echo 1)"

# explicit minor and patch
d="$scratch/minor"
new_fixture "$d" 1.4.7 "$changed_body"
out="$("$script" minor "$d" 2026-11-01 | tail -n 1)"
check "explicit minor prints 1.5.0" "$([ "$out" = 1.5.0 ] && echo 0 || echo 1)"
d="$scratch/patch"
new_fixture "$d" 1.4.7 "$added_body"
out="$("$script" patch "$d" 2026-11-01 | tail -n 1)"
check "explicit patch overrides Added: 1.4.8" "$([ "$out" = 1.4.8 ] && echo 0 || echo 1)"

# empty Unreleased fails and changes nothing
d="$scratch/empty"
new_fixture "$d" 1.0.0 $'\n'
cp "$d/CHANGELOG.md" "$d/CHANGELOG.before"
if "$script" auto "$d" 2026-11-01 > /dev/null 2>&1; then rc=1; else rc=0; fi
check "empty Unreleased fails" "$rc"
check "empty Unreleased leaves CHANGELOG untouched" "$(cmp -s "$d/CHANGELOG.md" "$d/CHANGELOG.before" && echo 0 || echo 1)"

# a heading with no entries under it still counts as empty
d="$scratch/headings-only"
new_fixture "$d" 1.0.0 $'\n### Changed\n\n'
if "$script" auto "$d" 2026-11-01 > /dev/null 2>&1; then rc=1; else rc=0; fi
check "Unreleased with only headings fails" "$rc"

# bad bump value fails
d="$scratch/badbump"
new_fixture "$d" 1.0.0 "$changed_body"
if "$script" huge "$d" 2026-11-01 > /dev/null 2>&1; then rc=1; else rc=0; fi
check "unknown bump fails" "$rc"

# changelog layout and footer links
d="$scratch/layout"
new_fixture "$d" 1.0.0 "$changed_body"
"$script" auto "$d" 2026-11-01 > /dev/null
expected_top=$'## [Unreleased]\n\n## [1.0.1] - 2026-11-01\n\n### Changed\n\n- A change.\n  continued here.\n\n## [1.0.0] - 2026-10-30'
actual_top="$(sed -n '/^## \[Unreleased\]/,/^## \[1.0.0\]/p' "$d/CHANGELOG.md")"
check "Unreleased is empty and the entries moved under the new version" "$([ "$actual_top" = "$expected_top" ] && echo 0 || echo 1)"
check "footer [Unreleased] compares from the new tag" "$(grep -qxF '[Unreleased]: https://github.com/o/r/compare/v1.0.1...HEAD' "$d/CHANGELOG.md" && echo 0 || echo 1)"
check "footer gets the new version link" "$(grep -qxF '[1.0.1]: https://github.com/o/r/compare/v1.0.0...v1.0.1' "$d/CHANGELOG.md" && echo 0 || echo 1)"
check "new link sits right after [Unreleased]" "$([ "$(grep -A1 '^\[Unreleased\]:' "$d/CHANGELOG.md" | tail -n 1)" = '[1.0.1]: https://github.com/o/r/compare/v1.0.0...v1.0.1' ] && echo 0 || echo 1)"
check "older footer links are kept" "$(grep -qxF '[1.0.0]: https://github.com/o/r/compare/v1.0.0-rc.1...v1.0.0' "$d/CHANGELOG.md" && echo 0 || echo 1)"

# Cargo.lock: only the lazarobox-shell entry changes
d="$scratch/lock"
new_fixture "$d" 1.0.0 "$changed_body"
cp "$d/Cargo.lock" "$d/Cargo.lock.before"
cp "$d/Cargo.toml" "$d/Cargo.toml.before"
"$script" auto "$d" 2026-11-01 > /dev/null
lock_diff="$(diff "$d/Cargo.lock.before" "$d/Cargo.lock" | grep '^[<>]' || true)"
check "Cargo.lock changes only the package version line" "$([ "$lock_diff" = $'< version = "1.0.0"\n> version = "1.0.1"' ] && echo 0 || echo 1)"
check "Cargo.lock bumped the right entry" "$(awk '/name = "lazarobox-shell"/ {getline; print}' "$d/Cargo.lock" | grep -qx 'version = "1.0.1"' && echo 0 || echo 1)"
toml_diff="$(diff "$d/Cargo.toml.before" "$d/Cargo.toml" | grep -c '^[<>]' || true)"
check "Cargo.toml changes only one line (dependency version untouched)" "$([ "$toml_diff" -eq 2 ] && grep -q 'serde = { version = "1.0.0" }' "$d/Cargo.toml" && echo 0 || echo 1)"

# the release workflow must be able to read the new section
d="$scratch/section"
new_fixture "$d" 1.0.0 "$changed_body"
"$script" auto "$d" 2026-11-01 > /dev/null
notes="$("$section" 1.0.1 "$d/CHANGELOG.md")"
check "changelog-section.sh reads the new section" "$([ "$notes" = $'### Changed\n\n- A change.\n  continued here.' ] && echo 0 || echo 1)"

# pre-release rule: auto and patch finalize the base; minor and major bump from it
d="$scratch/rc-auto"
new_fixture "$d" 1.1.0-rc.1 "$changed_body"
out="$("$script" auto "$d" 2026-11-01 | tail -n 1)"
check "auto on 1.1.0-rc.1 finalizes 1.1.0" "$([ "$out" = 1.1.0 ] && echo 0 || echo 1)"
d="$scratch/rc-auto-added"
new_fixture "$d" 1.1.0-rc.1 "$added_body"
out="$("$script" auto "$d" 2026-11-01 | tail -n 1)"
check "auto on a pre-release ignores Added: 1.1.0" "$([ "$out" = 1.1.0 ] && echo 0 || echo 1)"
d="$scratch/rc-patch"
new_fixture "$d" 1.1.0-rc.1 "$changed_body"
out="$("$script" patch "$d" 2026-11-01 | tail -n 1)"
check "patch on 1.1.0-rc.1 finalizes 1.1.0" "$([ "$out" = 1.1.0 ] && echo 0 || echo 1)"
d="$scratch/rc-minor"
new_fixture "$d" 1.1.0-rc.1 "$changed_body"
out="$("$script" minor "$d" 2026-11-01 | tail -n 1)"
check "minor on 1.1.0-rc.1 gives 1.2.0" "$([ "$out" = 1.2.0 ] && echo 0 || echo 1)"
d="$scratch/rc-major"
new_fixture "$d" 1.1.0-rc.1 "$changed_body"
out="$("$script" major "$d" 2026-11-01 | tail -n 1)"
check "major on 1.1.0-rc.1 gives 2.0.0" "$([ "$out" = 2.0.0 ] && echo 0 || echo 1)"

# the previous tag may itself be a pre-release (1.1.0-rc.1 -> 1.1.0)
d="$scratch/rc-footer"
new_fixture "$d" 1.1.0-rc.1 "$changed_body"
sed -i 's#compare/v1.0.0...HEAD#compare/v1.1.0-rc.1...HEAD#' "$d/CHANGELOG.md"
"$script" auto "$d" 2026-11-01 > /dev/null
check "footer link from a pre-release tag" "$(grep -qxF '[1.1.0]: https://github.com/o/r/compare/v1.1.0-rc.1...v1.1.0' "$d/CHANGELOG.md" && echo 0 || echo 1)"

echo
echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
